tests, gaps = [], []
for story in stories:
    if not story["criteria"]:
        gaps.append(f"{story['id']}: no acceptance criteria")
    for i, criterion in enumerate(story["criteria"], 1):
        m = re.match(r"Given (.+?), when (.+?), then (.+)", criterion, re.I)
        if not m:
            gaps.append(f"{story['id']} criterion {i}: not in Given/When/Then form")
            continue
        slug = re.sub(r"[^a-z0-9]+", "_", m.group(3).lower()).strip("_")
        tests.append(f"test_{story['id'].lower()}_{slug}")
return tests, gaps

errors = []
if not data.get("name", "").strip(): errors.append("name is required")
if not EMAIL.match(data.get("email", "")): errors.append("email is invalid")
elif any(r["email"].lower() == data["email"].lower() and r["id"] != data.get("id") for r in self.rows.values()): errors.append("email already exists")
if data.get("stage", "new") not in STAGES: errors.append("unknown stage")
if data.get("value", 0) < 0: errors.append("value must not be negative")
return errors

